D = "ivx_structural"
ITEMS = [
dict(d=D, c="ivx kernberg structural interview cycles", m="ask", l=3, hard=True,
q="Kernberg’s structural interview proceeds in cycles. What happens when the interviewer notices an inconsistency, such as a patient describing her mother as a saint and, minutes later, as cruel and humiliating?",
a="The interviewer clarifies, then gently confronts the contradiction, and observes how the patient responds",
ae="The structural interview uses clarification (inviting elaboration of vague or contradictory material), confrontation (tactfully bringing together contradictory elements) and, carefully, tentative interpretation in the here and now. The patient’s response is diagnostic: a neurotic patient can reflect on the contradiction; a borderline patient may become confused, irritated or split further; a psychotic patient may lose reality testing.",
w=[("The interviewer ignores it, since contradictions are normal in emotional speech",
"Ignoring contradictions misses the core data of the structural interview: how the patient integrates (or fails to integrate) representations."),
("The interviewer immediately interprets the splitting as a defense against rage",
"Deep interpretations early are risky and premature. Kernberg advises clarification and confrontation before cautious interpretation."),
("The interviewer administers a standardized personality inventory to resolve it",
"Questionnaires can complement but cannot replace the interactive test of how the patient deals with confrontation.")],
x="Kernberg (1984, Severe Personality Disorders) designed the structural interview to assess identity integration, defensive operations and reality testing. The interview moves in cycles between symptoms, pathological traits and the interaction in the room. Its distinctive move is using the interview relationship itself as a probe of structure.",
s="Kernberg, Severe Personality Disorders (1984)",
h="Kernberg’s three C’s: Clarify, Confront, (careful) Construe. Watch what the patient does with the contradiction."),

dict(d=D, c="ivx kernberg reality testing test", m="eye", l=3, hard=True,
q="In the structural interview, how does Kernberg distinguish borderline from psychotic personality organization when the patient shows an odd behavior?",
a="Tactfully point out the behavior and see whether the patient can empathize with how it looks to ordinary social perception",
ae="Kernberg defined reality testing as the capacity to differentiate self from non-self, internal from external origins of perceptions, and to empathize with ordinary social criteria of reality. When confronted tactfully (“I notice you’ve been smiling while describing your father’s death; I wonder how that might look to someone else”), borderline patients can usually see the point and their functioning improves; psychotic patients become more disorganized or incorporate the interviewer into a delusional frame.",
w=[("Ask whether the patient has ever heard voices or seen things",
"Asking about hallucinations is necessary but not sufficient. Brief psychotic-like experiences occur in borderline organization, and the structural test concerns reality testing in the interaction."),
("Check whether the patient uses primitive defenses such as splitting",
"Both borderline and psychotic organizations use primitive defenses. Defenses do not discriminate between them; reality testing does."),
("Measure identity diffusion with a questionnaire",
"Identity diffusion is present in both borderline and psychotic organization. It distinguishes them from neurotic organization, not from each other.")],
x="Summary of Kernberg’s three criteria: neurotic organization shows integrated identity, mature defenses and intact reality testing; borderline organization shows identity diffusion, primitive defenses and intact (though fragile) reality testing; psychotic organization shows identity diffusion, primitive defenses and lost reality testing. The probe-and-observe approach is what makes the structural interview distinctive.",
s="Kernberg, Severe Personality Disorders (1984); STIPO",
h="Borderline vs psychotic: “Show the mirror.” Borderline can see the reflection; psychotic sees someone else in it."),

dict(d=D, c="ivx identity diffusion probe", m="ask", l=2,
q="You want to assess identity integration. Which prompt is most in the spirit of the structural interview and STIPO?",
a="“Describe yourself, your personality, how you are different from others, so I can form a living picture of you.”",
ae="Kernberg asks patients to describe themselves (and important others) so the interviewer can form a three-dimensional image. Integrated identity produces a nuanced, coherent, stable description. Identity diffusion produces vague, contradictory, shallow or chaotic descriptions, often with confusion or irritation.",
w=[("“Do you ever feel empty inside?”",
"Chronic emptiness is linked to identity diffusion but a yes/no question gives little structural information."),
("“On a scale of 1 to 10, how good is your self-esteem?”",
"Self-esteem ratings do not reveal integration. Narcissistic patients may rate themselves highly while having a fragile identity."),
("“What is your diagnosis, in your own opinion?”",
"Asking for self-diagnosis assesses insight and explanatory model, not identity integration.")],
x="The same prompt is applied to significant others: “Describe your mother, so I could get a sense of her as a person.” Lack of depth in descriptions of others (all good or all bad, or caricatures) shows unintegrated object representations. This is often more revealing than symptom review.",
s="Kernberg, Severe Personality Disorders; Clarkin et al., STIPO",
h="Identity probe: “Paint yourself in 3D.” Flat painting = flat (diffuse) identity."),

dict(d=D, c="ivx stipo domains", m="ask", l=3, hard=True,
q="The Structured Interview of Personality Organization (STIPO, and its revision STIPO-R) rates several domains. Which list is closest to the STIPO-R domains?",
a="Identity, object relations, defenses (lower- and higher-level), aggression, and moral values",
ae="STIPO-R, from the Personality Disorders Institute at Weill Cornell, rates identity, object relations, primitive (lower-level) defenses, higher-level defenses, aggression and moral values. Ratings are combined into a level of personality organization from normal through neurotic to high, middle and low borderline.",
w=[("Openness, conscientiousness, extraversion, agreeableness, and neuroticism",
"These are the Big Five personality traits, measured by questionnaires such as the NEO, not structural domains."),
("Self-direction, empathy, intimacy, and identity, from DSM-5 Section III",
"These are the DSM-5 Level of Personality Functioning Scale components. They overlap conceptually but are not the STIPO domains."),
("Attachment, affect regulation, mentalization, and epistemic trust",
"These are mentalization-based constructs, important but not the STIPO-R structure.")],
x="STIPO grew out of Kernberg’s structural interview but is semi-structured and rated, making it usable in research. It has shown good reliability and predicts treatment course. Read carefully: the original STIPO included additional domains such as coping/rigidity and reality testing; STIPO-R simplified the structure.",
s="Clarkin, Caligor, Stern & Kernberg, STIPO-R (Personality Disorders Institute)",
h="STIPO-R: “I Object, Defend, Attack, Moralize” — Identity, Object relations, Defenses, Aggression, Moral values."),

dict(d=D, c="ivx aai grice", m="eye", l=3, hard=True,
q="In coding the Adult Attachment Interview (AAI), Mary Main drew on Grice’s maxims of cooperative conversation. A speaker says her childhood was “normal, really lovely,” gives the five adjectives “loving, caring, normal, nice, supportive,” but cannot recall a single specific supportive memory and insists she cannot remember childhood. Which classification and maxim violation is suggested?",
a="Dismissing: idealization unsupported by memories violates the maxim of quality",
ae="The dismissing classification is marked by idealization of parents, insistence on lack of memory, and minimization of attachment. When the adjectives are not supported (or are contradicted) by specific episodic memories, the speaker violates Grice’s maxim of quality (be truthful and have evidence). Brevity also often violates quantity (too little).",
w=[("Preoccupied: violates the maxim of manner through long, entangled answers",
"Preoccupied transcripts are often long, angry or passive and confused, violating manner and quantity in the opposite direction (too much). This vignette shows the opposite pattern."),
("Secure-autonomous: the brief answers show emotional containment",
"Secure speakers support adjectives with specific memories and can discuss difficulties coherently. Unsupported idealization argues against security."),
("Unresolved: the inability to remember signals a lapse in monitoring of reasoning",
"Unresolved status is coded from lapses specifically around loss or abuse (e.g., speaking of a dead person as alive). Generalized lack of recall is a dismissing marker.")],
x="Grice’s maxims are quality (be truthful, with evidence), quantity (be as informative as needed), relation (be relevant) and manner (be clear and orderly). The AAI is sometimes said to aim at “surprising the unconscious”: its rapid sequence of probing questions makes it hard to maintain a defensive narrative. Coherence of discourse, not the content of the childhood itself, predicts the speaker’s infant’s attachment (van IJzendoorn, 1995). This is why “earned security” exists.",
s="George, Kaplan & Main, Adult Attachment Interview; Main, Hesse & Goldwyn coding system",
h="AAI: “It’s not what happened, it’s how you tell it.” Five lovely adjectives with no memories = a shop window with no stock."),

dict(d=D, c="ivx aai unresolved", m="eye", l=3, hard=True,
q="During the AAI, while discussing her grandmother’s death 20 years earlier, a woman says, “She’s so happy now that I visit her every Sunday,” and then falls silent for 30 seconds. How is this coded?",
a="A lapse in the monitoring of reasoning about loss, suggesting unresolved/disorganized status",
ae="Unresolved status is assigned from lapses in monitoring of reasoning or discourse during discussions of loss or abuse: speaking of a dead person as if alive, prolonged unusual silences, eulogistic speech, or confusion about time and causality. These are thought to reflect intrusions of dissociated or disorganized states.",
w=[("Normal grief, because speaking of the dead in the present tense is culturally common",
"Some cultural expressions of continuing bonds are normal. The coding system distinguishes them from lapses where the speaker appears to believe, momentarily, that the person is physically alive."),
("A dismissing marker because she avoids talking about her feelings",
"Dismissing speakers minimize and idealize; this pattern is a lapse in monitoring, which is the unresolved code."),
("Evidence of psychosis, which requires referral",
"These brief lapses are common in non-psychotic samples and are not considered psychotic symptoms.")],
x="Unresolved classification in parents is associated with disorganized attachment in their infants (Main & Hesse). Main and Hesse proposed that frightened or frightening parental behavior mediates this link. For interviewers outside research, the AAI teaches a skill: listen not only to what is said about trauma but to the state of mind during the telling.",
s="Main & Hesse (1990); Hesse, Handbook of Attachment",
h="Unresolved = “the clock stops in the sentence.” Past tense slips to present: the dead come back alive in grammar."),

dict(d=D, c="ivx reflective functioning probes", m="ask", l=3, hard=True,
q="Fonagy’s Reflective Functioning (RF) scale is coded from AAI transcripts using “demand questions.” Which is a demand question?",
a="“Why do you think your parents behaved as they did during your childhood?”",
ae="Demand questions explicitly invite the speaker to reflect on mental states: why parents behaved as they did, how childhood affected one’s adult personality, whether one felt rejected. Responses are rated for awareness of the nature of mental states, explicit efforts to tease out mental states underlying behavior, recognition of developmental aspects, and awareness of mental states in relation to the interviewer.",
w=[("“Describe a specific memory of being upset as a child.”",
"This question asks for episodic memory, a core AAI question but not, by itself, a demand for reflection."),
("“Give me five adjectives describing your relationship with your mother.”",
"Adjective selection is a standard AAI prompt and taps semantic representation, not reflective function."),
("“Where did you live when you were six?”",
"Biographical facts do not demand reflection.")],
x="RF ranges from negative (bizarre or hostile refusal to reflect) through absent, questionable, ordinary and marked to exceptional. Low RF is associated with borderline personality disorder and transmission of insecure attachment. Clinically, you can borrow demand questions in ordinary interviews: “Why do you think he did that?” or “What do you think was going on in your mind then?” and listen for nuanced, tentative, developmental answers versus concrete or pseudo-mentalizing ones.",
s="Fonagy, Target, Steele & Steele, Reflective Functioning Manual (1998)",
h="Demand question: “Why do they do what they do?” RF = the mind-reading muscle under load."),

dict(d=D, c="ivx pseudomentalizing", m="eye", l=3, hard=True,
q="A patient speaks fluently about her “attachment wounds,” her “inner child,” and her mother’s “narcissistic injury,” yet each explanation is certain, elaborate, and serves to justify her anger. What does mentalization theory call this?",
a="Pseudomentalizing, often of the hypermentalizing type, with excessive certainty and self-serving content",
ae="Pseudomentalizing looks like reflection but lacks key features of genuine mentalizing: tentativeness, curiosity, acknowledgment of opacity of minds, and connection with real affect. Hypermentalizing involves elaborate, over-certain attributions. Psychological jargon can make it look sophisticated.",
w=[("Excellent reflective functioning, which predicts a good psychotherapy outcome",
"Genuine high RF involves uncertainty and openness to alternative perspectives. Over-certain, self-justifying accounts are not high RF."),
("Teleological mode, in which only observable actions count",
"Teleological thinking focuses on physical actions (“If he loved me, he would come”). This patient uses mental-state language, though in a distorted way."),
("Psychic equivalence, in which thoughts are experienced as reality",
"Psychic equivalence is closer to this than teleological mode, but the defining feature here is pseudomentalizing with elaborate jargon.")],
x="MBT (Bateman & Fonagy) describes prementalizing modes: psychic equivalence (inner = outer), pretend mode (thoughts disconnected from reality and affect; pseudomentalizing belongs here), and teleological mode (only actions count). Interview technique: gently ask for the evidence and alternatives, and slow down: “How do you know that’s what she felt? Could there be another reason?” The patient’s response distinguishes pretend mode from genuine reflection.",
s="Bateman & Fonagy, Mentalization-Based Treatment for Personality Disorders",
h="Pseudomentalizing = “psychology costume, no psychology inside.” Real mentalizing is curious and unsure."),

dict(d=D, c="ivx opd2 axes", m="ask", l=3, hard=True,
q="The German Operationalized Psychodynamic Diagnosis system (OPD-2) uses a semi-structured interview to rate several axes. Which set describes them?",
a="Experience of illness and prerequisites for treatment, interpersonal relations, conflict, structure, and mental and psychosomatic disorders",
ae="OPD-2 has five axes: I (experience of illness and prerequisites for treatment), II (interpersonal relations, including dysfunctional relational patterns), III (conflict, e.g., dependence vs autonomy, submission vs control, desire for care vs autarky), IV (structure, rated across perception, regulation, communication and attachment) and V (ICD/DSM diagnosis).",
w=[("Clinical syndromes, personality disorders, medical conditions, psychosocial stressors, and global functioning",
"These were the five axes of DSM-IV, not OPD-2."),
("Id, ego, superego, external reality, and the ego ideal",
"These are elements of Freud’s structural theory, not OPD axes."),
("Self-functioning, interpersonal functioning, trait domains, and pervasiveness",
"These belong to DSM-5’s Alternative Model for Personality Disorders.")],
x="OPD-2 is widely used in German-speaking countries for treatment planning and research. Its conflict axis is particularly useful: it names conflicts in operational terms (individuation vs dependency, submission vs control, need for care vs self-sufficiency, self-value conflict, guilt conflict, oedipal conflict, identity conflict) and links them to focus selection in therapy.",
s="OPD Task Force, Operationalized Psychodynamic Diagnosis OPD-2 (2008)",
h="OPD-2 axes: “Ill, Inter, Conflict, Structure, Diagnosis” — I-I-C-S-D: “I Interview Carefully, Structure Diagnoses.”"),

dict(d=D, c="ivx swap clinical diagnostic interview", m="ask", l=3, hard=True,
q="The Shedler-Westen Assessment Procedure (SWAP-200) is often scored after the Clinical Diagnostic Interview (CDI). What is the central principle of the CDI?",
a="Elicit narratives about specific relationships and events so the clinician can infer personality, rather than asking patients to describe their traits directly",
ae="Westen and Shedler argued that personality, especially defenses and implicit relational patterns, is poorly captured by self-report. The CDI asks for detailed narratives (“Tell me about a time you felt let down by someone close”), and the clinician infers patterns, then sorts 200 statements in the SWAP-200 Q-sort.",
w=[("Ask the patient to rate each DSM personality criterion on a Likert scale",
"This is how self-report inventories work. The CDI deliberately avoids direct self-attribution."),
("Administer projective tests such as the Rorschach before the interview",
"The SWAP does not require projective testing."),
("Interview the patient’s family to obtain an outside view of personality",
"Collateral information can help, but the CDI is a direct clinical interview.")],
x="The SWAP-200 yields a dimensional profile and matches to empirically derived personality prototypes. It formed part of the empirical basis of the PDM-2’s P axis. The interview principle is broadly useful: “Tell me about…” elicits personality; “Are you the kind of person who…?” elicits self-image.",
s="Westen & Shedler, Am J Psychiatry 1999; Shedler, Westen & Lingiardi, The Evaluation of Psychoanalytic Personality (SWAP-200)",
h="CDI: “Show me the episode, not the self-portrait.”"),

dict(d=D, c="ivx kernberg psychotic interpretation response", m="eye", l=3, hard=True,
q="Kernberg proposed that interpretations given in the diagnostic interview have a predictable effect depending on structure. Which pattern did he describe?",
a="In borderline organization, a tactful interpretation of primitive defenses tends to improve functioning; in psychotic organization, it tends to worsen it",
ae="Kernberg observed that interpreting primitive defenses (for example, splitting expressed in the interview) helps the borderline patient integrate and test reality better in the moment, whereas the psychotic patient, lacking self-other boundaries, experiences interpretation as intrusion and regresses. This makes interpretation a diagnostic probe.",
w=[("Interpretations always worsen functioning in both organizations, so they should be avoided",
"Kernberg did not advise avoiding interpretation altogether in diagnostic interviews; he used it, carefully, as a probe."),
("Interpretations improve functioning in psychotic patients but worsen it in borderline patients",
"This reverses the pattern Kernberg described."),
("Interpretations have no predictable effect; diagnosis depends only on symptoms",
"Kernberg’s structural approach was a reaction against diagnosis by symptoms alone.")],
x="This principle has a parallel in the Lacanian tradition, which cautions against “triggering” psychosis by placing the subject before a question they cannot symbolize. Across schools, the wise interviewer uses interpretation sparingly in a first meeting and observes the response as data.",
s="Kernberg, Severe Personality Disorders (1984)",
h="Interpretation as litmus: borderline “clears,” psychotic “clouds.”"),

dict(d=D, c="ivx caligor neurotic level assessment", m="ask", l=3, hard=True,
q="Caligor, Kernberg and Clarkin describe assessment of higher-level (neurotic) personality pathology. What feature most distinguishes these patients from borderline-level patients during the interview?",
a="An integrated sense of self and others, so descriptions are coherent and nuanced, with rigid but more mature defenses",
ae="Higher-level personality pathology involves consolidated identity and integrated object relations, with rigidity in particular areas (for example, inhibition of sexuality or aggression, perfectionism). In the interview, patients can describe themselves and others coherently and tolerate confrontation. Their difficulties lie in specific conflicts, not in global identity diffusion.",
w=[("Absence of any defense mechanisms, since neurotic patients are healthy",
"Neurotic-level patients use defenses, mainly repression-based (repression, intellectualization, reaction formation). The problem is rigidity, not absence."),
("Frequent micro-psychotic episodes under stress",
"Transient psychotic experiences under stress are associated with borderline organization."),
("Inability to form a treatment alliance",
"Higher-level patients typically form alliances readily. Alliance difficulty is more typical of lower-level organization.")],
x="Their manual (Handbook of Dynamic Psychotherapy for Higher Level Personality Pathology, 2007) uses the structural interview plus attention to the patient’s presenting problems, identifying the dominant conflicts and the associated object relations, which are then targeted in Dynamic Psychotherapy (DPHP).",
s="Caligor, Kernberg & Clarkin, Handbook of Dynamic Psychotherapy for Higher Level Personality Pathology (2007)",
h="Neurotic level: “Solid house, stuck doors.” Borderline: “The walls themselves shift.”"),
]
